  "carryover": {
    "COMPLETED": "All hypotheses evaluated regarding Tesla's revenue start year.",
    "REMAINING": "-",
    "DECISIONS": "H-5a179e refuted, H-99b0c6 refuted, H-bbbcb8 refuted, H-9a7ea7 supported",
    "CONTEXT": "No XBRL facts (any concept) exist for Tesla before FY 2011 in the raw EDGAR data; facts appear from FY 2011 onward."
  },
  "answer": {
    "summary": "Tesla's revenue data begin in FY 2011 because the EDGAR XBRL repository contains no revenue or any other XBRL facts for Tesla prior to that year. This absence aligns with Tesla's status as a smaller reporting company before FY 2011, which was not required to submit XBRL‑tagged financials. Consequently, the earliest available revenue facts are from FY 2011, reflecting regulatory reporting thresholds rather than missing revenue.",
    "claims": [
      {
        "text": "The earliest fiscal year for which Tesla has any revenue fact in edgar.revenue_facts is 2011.",
        "evidence": ["E-ab997b"]
      },
      {
        "text": "There are zero revenue facts for Tesla before fiscal year 2011 in edgar.revenue_facts.",
        "evidence": ["E-26549a"]
      },
      {
        "text": "There are zero XBRL facts of any concept for Tesla before fiscal year 2011 in the raw EDGAR source.",
        "evidence": ["E-4850cc"]
      }
    ],
    "inferences": [
      {
        "text": "The lack of pre‑2011 XBRL facts is likely due to Tesla being a smaller reporting company before FY 2011, exempt from mandatory XBRL tagging.",
        "basis": "Claim 3 shows no XBRL facts before 2011; this matches the known SEC rule that smaller reporters were not required to file XBRL until later, supporting H-9a7ea7."
      },
      {
        "text": "Therefore the observed start of Tesla's revenue history in the data reflects reporting requirements, not absence of revenue.",
        "basis": "Claims 1‑3 establish the data boundary; inference attributes it to regulatory exemption rather than missing revenue."
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-5a179e",
        "status": "refuted",
        "evidence": ["E-26549a", "E-4850cc"],
        "why": "No revenue facts exist before 2011, and there are also no other XBRL facts, indicating the absence is not due to inconsistent tagging of the Revenues concept alone."
      },
      {
        "id": "H-99b0c6",
        "status": "refuted",
        "evidence": ["E-4850cc"],
        "why": "Zero XBRL facts before 2011 cannot be explained by minimal revenue; if revenue were reported (even as zero), XBRL would capture it."
      },
      {
        "id": "H-bbbcb8",
        "status": "refuted",
        "evidence": ["E-26549a", "E-4850cc"],
        "why": "The absence of pre‑2011 facts persists even when examining period_frame and raw source; no evidence that a hidden filter removing NULL period_frame rows is responsible."
      },
      {
        "id": "H-9a7ea7",
        "status": "supported",
        "evidence": ["E-4850cc", "E-ab997b"],
        "why": "No XBRL facts appear before FY 2011, consistent with Tesla's status as a smaller reporting company exempt from XBRL filing; facts appear from FY 2011 onward when the requirement applied."
      }
    ]
  }
